    form.addEventListener('click',event=>{const button=event.target.closest('button');if(!button||(button.dataset.add!=='quick'&&button.dataset.quickRemove===undefined))return;event.preventDefault();if(button.dataset.add==='quick'){form.querySelector('#home-quick').insertAdjacentHTML('beforeend','<article class="home-row"><label>Label<input data-quick data-field="label" value="New link"></label><label>Link<input data-quick data-field="href" value="/"></label><label>Icon / action<input data-quick data-field="action" value="section"></label><label class="toggle">Show<input type="checkbox" data-quick data-field="enabled" checked></label><button type="button" class="danger" data-quick-remove>Delete</button></article>');}else button.closest('.home-row')?.remove();},true);
