  function parse(content) { const match=content.match(/^---\s*\n([\s\S]*?)\n---\s*\n?([\s\S]*)$/); const data={body:match?match[2]:content}; if(!match)return data; match[1].split('\n').forEach(line=>{const m=line.match(/^([\w_]+):\s*(.*)$/);if(m){let v=m[2].trim().replace(/^['"]|['"]$/g,'');if(/^\d+$/.test(v))v=Number(v);if(v==='true'||v==='false')v=v==='true';if(/^\[.*\]$/.test(v)){try{v=JSON.parse(v)}catch{}}data[m[1]]=v;}}); return data; }
